def age_groups(values: pd.Series) -> pd.Series:
    """Create the four documented fairness age bands."""
    return pd.cut(
        values,
        bins=[-np.inf, 24, 34, 44, np.inf],
        labels=["under_25", "25_34", "35_44", "45_plus"],
    ).astype(str)
